from argparse import Namespaceimport loggingfrom typing import Callable, List, Unionimport numpy as npimport torchimport torch.nn as nnfrom torch.optim import Optimizerfrom torch.optim.lr_scheduler import _LRSchedulerimport tqdmfrom chemprop.data import MoleculeDatasetfrom chemprop.nn_utils import NoamLRdef train(model: nn.Module,          data: Union[MoleculeDataset, List[MoleculeDataset]],          loss_func: Callable,          optimizer: Optimizer,          scheduler: _LRScheduler,          args: Namespace):    model.train()    loss_list = []    uq_list = []    for batch, features_batch, targets in tqdm.tqdm(data):        optimizer.zero_grad()        valid = torch.where(targets == 0.5, 0., 1.)        if valid.sum()==0:            continue        means, uq, n_atoms, uq_out,a_scope,b_scope = model(batch, features_batch)        loss = loss_func(means, targets)        loss = torch.sum(loss * valid) / torch.sum(valid)        loss.backward()        optimizer.step()        if isinstance(scheduler, NoamLR):  # class            scheduler.step()    return len(data) * args.batch_size, loss_list, uq_list